        toolRow=new JPanel(new FlowLayout(FlowLayout.LEFT,6,6));toolbar.add(toolRow);JComboBox<String> templates=new JComboBox<>(new String[]{"Choose template…","Island mountains","Terraced ranges","Masked mountains","Coastal watershed","Frozen highlands","Wetland basin","Repository grove"});toolRow.add(templates);tool("Load template",()->{if(templates.getSelectedIndex()==0){error("Choose a graph template first.");return;}if(JOptionPane.showConfirmDialog(this,"Replace the node graph? Your current map will stay unchanged.","Load template",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){checkpoint();graph=TerrainGraph.template((String)templates.getSelectedItem());selected=graph.output();changed(true);inspector();canvas.fit();}});tool("Open graph",this::openGraph);tool("Save graph",this::saveGraph);tool("Export world",app::export);
