    void bind(String stroke,Runnable run){getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(stroke),stroke);getRootPane().getActionMap().put(stroke,new AbstractAction(){private static final long serialVersionUID=1L;public void actionPerformed(ActionEvent e){if(!app.busy&&!(KeyboardFocusManager.getCurrentKeyboardFocusManager().getFocusOwner() instanceof javax.swing.text.JTextComponent))run.run();}});}
    void adoptWorld(){if(worker!=null)worker.cancel(true);graph=app.world!=null&&app.world.graph!=null?app.world.graph.copy():TerrainGraph.template("Island mountains");selected=graph.output();undo.clear();redo.clear();fields=Map.of();thumbnails.clear();inspector();canvas.fit();queuePreview();}
    void setBusy(boolean busy){if(busy){if(worker!=null)worker.cancel(true);canvas.dragging=canvas.pending=-1;canvas.panning=false;}setEnabledDeep(toolbar,!busy);setEnabledDeep(properties,!busy);if(!busy)inspector();if(!busy&&isVisible())queuePreview();}
    static void setEnabledDeep(Container c,boolean enabled){for(Component child:c.getComponents()){child.setEnabled(enabled);if(child instanceof Container nested)setEnabledDeep(nested,enabled);}}
    void checkpoint(){undo.push(graph.copy());redo.clear();while(undo.size()>30)undo.removeLast();}
    void changed(boolean terrain){if(app.world!=null){app.world.graph=graph.copy();app.dirty=true;app.updateTitle();}if(terrain){revision++;fields=Map.of();thumbnails.clear();queuePreview();}canvas.repaint();}
    void undo(){if(undo.isEmpty())return;redo.push(graph.copy());graph=undo.pop();if(!graph.nodes.containsKey(selected))selected=graph.output();changed(true);inspector();}
    void redo(){if(redo.isEmpty())return;undo.push(graph.copy());graph=redo.pop();if(!graph.nodes.containsKey(selected))selected=graph.output();changed(true);inspector();}
    void addNode(){TerrainGraph before=graph.copy();try{TerrainGraph.Node n=graph.add((TerrainGraph.Type)palette.getSelectedItem(),canvas.worldX(canvas.getWidth()/2)-90,canvas.worldY(canvas.getHeight()/2)-60);undo.push(before);redo.clear();while(undo.size()>30)undo.removeLast();selected=n.id;changed(true);inspector();}catch(IllegalArgumentException e){error(e.getMessage());}}
    void deleteSelected(){if(!graph.nodes.containsKey(selected))return;checkpoint();graph.remove(selected);selected=-1;changed(true);inspector();}
    boolean connect(int from,int to,int slot){TerrainGraph before=graph.copy();try{graph.connect(from,to,slot);undo.push(before);redo.clear();while(undo.size()>30)undo.removeLast();changed(true);inspector();return true;}catch(IllegalArgumentException e){error(e.getMessage());return false;}}
    void error(String text){message.setForeground(new Color(255,174,140));message.setText(text);}
    void inspector(){properties.removeAll();TerrainGraph.Node n=graph.nodes.get(selected);JLabel heading=new JLabel(n==null?"Select a node":n.title());heading.setFont(heading.getFont().deriveFont(Font.BOLD,15));heading.setForeground(new Color(111,219,183));properties.add(heading);properties.add(Box.createVerticalStrut(14));if(n!=null){for(TerrainGraph.Param p:n.type.params){properties.add(new JLabel(p.label()));if(n.type==TerrainGraph.Type.TREES&&(p.key().equals("library")||p.key().equals("group")||p.key().equals("variant"))){properties.add(treeChoice(n,p.key()));}else if(n.type==TerrainGraph.Type.LAKE&&p.key().equals("random")){JComboBox<String> placement=new JComboBox<>(new String[]{"Manual X / Z","Random (seeded)"});placement.setSelectedIndex((int)n.p("random"));placement.setMaximumSize(new Dimension(235,34));placement.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put("random",(double)placement.getSelectedIndex());changed(true);inspector();});properties.add(placement);}else if(n.type==TerrainGraph.Type.BLEND&&p.key().equals("mode")){JComboBox<String> mode=new JComboBox<>(new String[]{"Mix","Add (relative to sea)","Maximum","Minimum","Subtract","Multiply"});mode.setSelectedIndex((int)n.p("mode"));mode.setMaximumSize(new Dimension(235,34));mode.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put(p.key(),(double)mode.getSelectedIndex());changed(true);});properties.add(mode);}else{JSpinner spin=new JSpinner(new SpinnerNumberModel(n.p(p.key()),p.min(),p.max(),p.step()));spin.setMaximumSize(new Dimension(235,32));if(n.type==TerrainGraph.Type.LAKE&&(p.key().equals("x")||p.key().equals("z")))spin.setEnabled(n.p("random")<.5);spin.addChangeListener(e->{if(app.busy)return;checkpoint();n.values.put(p.key(),((Number)spin.getValue()).doubleValue());changed(true);});properties.add(spin);}properties.add(Box.createVerticalStrut(12));if(n.type==TerrainGraph.Type.TREES&&p.key().equals("variant"))treeSummary(n);}
            if(n.type==TerrainGraph.Type.COAST){JButton reroll=new JButton("Randomize flat patches");reroll.setMaximumSize(new Dimension(235,34));reroll.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put("flatSeed",n.p("flatSeed")>=100000?-100000:n.p("flatSeed")+1);if(n.p("flatAmount")==0)n.values.put("flatAmount",.5);changed(true);inspector();});properties.add(reroll);properties.add(Box.createVerticalStrut(12));}
            if(n.type==TerrainGraph.Type.ROCKS){JButton reroll=new JButton("Randomize rocks");reroll.setMaximumSize(new Dimension(235,34));reroll.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put("seed",n.p("seed")>=100000?-100000:n.p("seed")+1);changed(true);inspector();});properties.add(reroll);properties.add(Box.createVerticalStrut(12));}
            if(n.type==TerrainGraph.Type.RIVERS){JButton reroll=new JButton("Randomize rivers");reroll.setMaximumSize(new Dimension(235,34));reroll.setToolTipText("Choose new headwaters on the same terrain. The river seed is saved with the graph.");reroll.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put("riverSeed",n.p("riverSeed")>=100000?-100000:n.p("riverSeed")+1);changed(true);inspector();});properties.add(reroll);properties.add(Box.createVerticalStrut(12));}
            if(n.type==TerrainGraph.Type.LAKE){JButton reroll=new JButton("New random location");reroll.setMaximumSize(new Dimension(235,34));reroll.addActionListener(e->{if(app.busy)return;checkpoint();n.values.put("random",1.0);n.values.put("locationSeed",n.p("locationSeed")>=100000?-100000:n.p("locationSeed")+1);changed(true);inspector();});properties.add(reroll);properties.add(Box.createVerticalStrut(12));}
            if(n.input.length>0){JLabel title=new JLabel("INPUT CONNECTIONS");title.setForeground(new Color(167,184,194));properties.add(title);properties.add(Box.createVerticalStrut(6));for(int j=0;j<n.input.length;j++){final int slot=j;TerrainGraph.Node from=graph.nodes.get(n.input[j]);JButton disconnect=new JButton((n.type==TerrainGraph.Type.BLEND&&j==2?"Mask":n.type.port(j))+": "+(from==null?"none":from.type.title));disconnect.setToolTipText((from==null?"Unconnected":from.title())+" · click to disconnect");disconnect.setMaximumSize(new Dimension(235,32));disconnect.setEnabled(from!=null&&!app.busy);disconnect.addActionListener(e->{if(app.busy)return;checkpoint();n.input[slot]=-1;changed(true);inspector();});properties.add(disconnect);properties.add(Box.createVerticalStrut(5));}}
        }properties.add(Box.createVerticalStrut(18));JTextArea help=new JTextArea("Drag from an output dot to an input dot. Or click output, then input.\n\nGreen: terrain · Purple: mask.\nBlue: water · Orange: climate.\nYellow: material · Pink: biome.\nRight drag: pan · Wheel: zoom\nDrag node header: move\n\nBuild uses the World tab size, seed and sea level, plus Terrain surface rules. Painting stays separate until the next Build.");help.setEditable(false);help.setFocusable(false);help.setLineWrap(true);help.setWrapStyleWord(true);help.setOpaque(false);help.setFont(new Font("SansSerif",Font.PLAIN,12));help.setForeground(new Color(167,184,194));help.setMaximumSize(new Dimension(235,230));((javax.swing.text.DefaultCaret)help.getCaret()).setUpdatePolicy(javax.swing.text.DefaultCaret.NEVER_UPDATE);properties.add(help);for(Component child:properties.getComponents())if(child instanceof JComponent c){c.setAlignmentX(0);c.setMinimumSize(new Dimension(0,c.getMinimumSize().height));}properties.revalidate();properties.repaint();SwingUtilities.invokeLater(()->{if(propertyScroll!=null)propertyScroll.getVerticalScrollBar().setValue(0);});if(app.busy)setEnabledDeep(properties,false);}
    void treeSummary(TerrainGraph.Node n){try{TreeLibrary.Tree tree=TreeLibrary.selected(n);JLabel image=new JLabel(new ImageIcon(TreeLibrary.thumbnail(tree).getScaledInstance(176,136,Image.SCALE_SMOOTH)));image.setMaximumSize(new Dimension(235,140));properties.add(image);JLabel info=new JLabel(tree.states.length+" blocks · source cell "+tree.sourceCell);info.setForeground(new Color(167,184,194));properties.add(info);properties.add(new JLabel("Repeats this variant; groups never mix."));properties.add(Box.createVerticalStrut(12));}catch(IllegalArgumentException e){properties.add(new JLabel("Select a valid tree group and variant."));}}
    JComboBox<String> treeChoice(TerrainGraph.Node node,String key){TreeLibrary.Catalog catalog=TreeLibrary.catalog();List<String> items=new ArrayList<>();if(key.equals("library"))items.add("Exsilits tree repository");else if(key.equals("group")){for(int i=0;i<catalog.groups().size();i++)items.add(catalog.groups().get(i)+" ("+catalog.byGroup().get(i).size()+")");}else{int group=(int)node.p("group");if(group>=0&&group<catalog.groups().size())for(TreeLibrary.Tree tree:catalog.byGroup().get(group))items.add(tree.toString());}JComboBox<String> box=new JComboBox<>(items.toArray(new String[0]));int index=(int)node.p(key);box.setSelectedIndex(index>=0&&index<items.size()?index:-1);box.setMaximumSize(new Dimension(235,34));box.setToolTipText(key.equals("group")?"Groups describe source trunk/canopy materials. Only your selected exact variant is scattered.":key.equals("variant")?"Choose one original source-cell tree; no random variant mixing.":catalog.source());box.addActionListener(e->{if(app.busy||box.getSelectedIndex()<0)return;checkpoint();node.values.put(key,(double)box.getSelectedIndex());if(key.equals("group"))node.values.put("variant",0.0);changed(true);inspector();});return box;}
    void queuePreview(){if(debounce==null)return;revision++;if(worker!=null)worker.cancel(true);debounce.restart();}
    void refreshPreview(){if(!isVisible()||app.busy)return;if(worker!=null)worker.cancel(true);TerrainGraph snapshot=graph.copy();int target=previewSelected.isSelected()&&graph.nodes.containsKey(selected)?selected:graph.output();long current=++revision;int water=app.sea.getValue(),size=Integer.parseInt((String)app.size.getSelectedItem());long seed=app.seedValue();if(size>2048){fields=Map.of();environments=Map.of();thumbnails.clear();preview.image=null;preview.repaint();canvas.repaint();message.setText(size+" × "+size+" selected · Live preview paused. "+(size==16384?"Use Build into map to build in the editor.":"Build into map to generate terrain.")+"");return;}message.setForeground(new Color(180,201,210));message.setText("Evaluating "+size+" × "+size+" preview…");worker=new SwingWorker<>(){protected TerrainGraph.Result doInBackground(){return snapshot.evaluate(size,size,water,seed,target,()->isCancelled());}protected void done(){if(isCancelled()||current!=revision)return;try{TerrainGraph.Result result=get();previewResolution=size;fields=result.fields();environments=result.environments();thumbnails.clear();preview.image=nodeImage(snapshot.nodes.get(target),result.output(),result.environment(),water);preview.repaint();canvas.repaint();message.setForeground(new Color(150,216,185));message.setText("Preview · "+previewResolution+"² · "+snapshot.nodes.get(target).title()+"   |   Preview matches build resolution"+(result.environment().trees.isEmpty()?"":" · "+result.environment().trees.size()+" trees"));}catch(Exception e){fields=Map.of();thumbnails.clear();preview.image=null;preview.repaint();canvas.repaint();Throwable cause=e.getCause()==null?e:e.getCause();error(cause.getMessage());}}};worker.execute();}
    void saveGraph(){JFileChooser c=new JFileChooser();c.setSelectedFile(new File("terrain.tgraph"));if(c.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;File file=c.getSelectedFile();if(!file.getName().endsWith(".tgraph"))file=new File(file.getPath()+".tgraph");if(file.exists()&&JOptionPane.showConfirmDialog(this,"Replace this graph?","Save graph",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{writeFile(graph,file.toPath());message.setText("Graph saved: "+file);}catch(IOException e){error(e.getMessage());}}
    static void writeFile(TerrainGraph graph,Path path)throws IOException{Path absolute=path.toAbsolutePath(),temp=Files.createTempFile(absolute.getParent(),".terrain-graph-",".tmp");try{try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(temp))){out.writeUTF("TERRAGRAPH1");graph.write(out);}try{Files.move(temp,absolute,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,absolute,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
    static TerrainGraph readFile(Path path)throws IOException{
        if(!Files.isRegularFile(path))throw new IOException("Choose a saved .tgraph graph or .terra project file.");
        try(BufferedInputStream bytes=new BufferedInputStream(Files.newInputStream(path))){
            bytes.mark(2);int first=bytes.read(),second=bytes.read();bytes.reset();
            if(first==0x1f&&second==0x8b){TerrainGraph saved=TerraForge.readProject(path).graph;if(saved==null)throw new IOException("This project has no saved node graph. Open it with the main window's Open button to view its terrain.");return saved.copy();}
            DataInputStream in=new DataInputStream(bytes);
            if(!in.readUTF().equals("TERRAGRAPH1"))throw new IOException("This is not a TerraForge graph. Choose a .tgraph file or a .terra project containing nodes.");
            return TerrainGraph.read(in);
        }catch(EOFException e){throw new IOException("The graph file is incomplete or is not a TerraForge graph.",e);}
    }
    static File graphDirectory(){
        try{Path location=Path.of(GraphEditor.class.getProtectionDomain().getCodeSource().getLocation().toURI());Path base=location.getParent();Path examples=base.resolve("examples");if(Files.isDirectory(examples))return examples.toFile();}catch(Exception ignored){}
        Path examples=Path.of("examples");return (Files.isDirectory(examples)?examples:Path.of(System.getProperty("user.dir"))).toFile();
    }
    JFileChooser graphChooser(){JFileChooser c=new JFileChooser(graphDirectory());c.setDialogTitle("Open terrain graph or project");c.setFileFilter(new FileNameExtensionFilter("TerraForge graphs and projects (*.tgraph, *.terra)","tgraph","terra"));return c;}
    void installGraph(TerrainGraph loaded){checkpoint();graph=loaded;selected=graph.output();canvas.pending=canvas.dragging=-1;canvas.wireEnd=null;changed(true);inspector();canvas.fit();}
    void openGraph(){
        try{JFileChooser c=graphChooser();if(c.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;TerrainGraph loaded=readFile(c.getSelectedFile().toPath());
            if(JOptionPane.showConfirmDialog(this,"Replace the current graph? Your current map will stay unchanged.\nUse Build into map to generate terrain from the opened graph.","Open graph",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
            installGraph(loaded);
        }catch(IOException|RuntimeException e){String detail=e.getMessage()==null?"The file could not be read.":e.getMessage();error(detail);JOptionPane.showMessageDialog(this,detail,"Cannot open graph",JOptionPane.ERROR_MESSAGE);}
    }
    static Color channelColor(TerrainGraph.Channel channel){return switch(channel){case WATER->new Color(103,183,238);case MASK->new Color(187,145,237);case CLIMATE->new Color(238,163,98);case MATERIAL->new Color(215,195,106);case BIOME->new Color(231,153,191);default->new Color(103,213,178);};}
    BufferedImage nodeImage(TerrainGraph.Node node,float[] field,EnvironmentMap env,int sea){if(node.type.channel()==TerrainGraph.Channel.TERRAIN&&env!=null){TerraForge.World w=new TerraForge.World(previewResolution,sea,0);w.height=env.height;w.environment=env;w.settings=app.generationSettings();return EnvironmentView.render(w,layer.getSelectedIndex());}if(node.type.channel()==TerrainGraph.Channel.MASK)return image(field,previewResolution,sea,true);BufferedImage out=new BufferedImage(previewResolution,previewResolution,BufferedImage.TYPE_INT_RGB);for(int i=0;i<field.length;i++){Color c=switch(node.type.channel()){case MATERIAL->EnvironmentView.material(Math.round(field[i]));case BIOME->EnvironmentView.BIOME_COLORS[Math.max(0,Math.min(EnvironmentView.BIOME_COLORS.length-1,Math.round(field[i])))];case CLIMATE->EnvironmentView.gradient(field[i],new Color(80,136,230),new Color(241,117,66));default->EnvironmentView.gradient((field[i]+64)/364,new Color(15,45,90),new Color(90,214,238));};out.setRGB(i%previewResolution,i/previewResolution,c.getRGB());}return out;}
    static BufferedImage image(float[] heights,int n,int sea,boolean mask){BufferedImage image=new BufferedImage(n,n,BufferedImage.TYPE_INT_RGB);for(int z=0;z<n;z++)for(int x=0;x<n;x++){float h=heights[z*n+x];Color color;if(mask){int v=(int)(TerrainGenerator.clamp(h,0,1)*255);color=new Color(v,v,v);}else{color=h<=sea?new Color(27,Math.max(40,110-(int)(sea-h)),157):h>145?new Color(225,233,234):h<sea+3?new Color(215,197,139):new Color(86,146,82);double shade=x>0&&z>0?TerrainGenerator.clamp(1+(heights[z*n+x-1]-h)*.035+(heights[(z-1)*n+x]-h)*.02,.5,1.35):1;color=new Color((int)Math.min(255,color.getRed()*shade),(int)Math.min(255,color.getGreen()*shade),(int)Math.min(255,color.getBlue()*shade));}image.setRGB(x,z,color.getRGB());}return image;}
    static class PropertyPanel extends JPanel implements Scrollable {private static final long serialVersionUID=1L;public Dimension getPreferredScrollableViewportSize(){return getPreferredSize();}public int getScrollableUnitIncrement(Rectangle visible,int orientation,int direction){return 16;}public int getScrollableBlockIncrement(Rectangle visible,int orientation,int direction){return Math.max(16,visible.height-16);}public boolean getScrollableTracksViewportWidth(){return true;}public boolean getScrollableTracksViewportHeight(){return false;}}
    class Preview extends JPanel {private static final long serialVersionUID=1L;BufferedImage image;Preview(){setBackground(new Color(17,25,32));}protected void paintComponent(Graphics graphics){super.paintComponent(graphics);if(image!=null){int s=Math.min(getWidth(),getHeight())-8;graphics.drawImage(image,(getWidth()-s)/2,4,s,s,null);}else{graphics.setColor(new Color(167,184,194));if(mapSize!=null&&Integer.parseInt((String)mapSize.getSelectedItem())>2048){graphics.drawString("Large-map preview paused",12,35);graphics.drawString("Use the build/export button below size.",12,55);}else graphics.drawString("Connect nodes to preview terrain",12,35);}}}
    class GraphCanvas extends JPanel {
        private static final long serialVersionUID=1L;static final int WIDTH=184,HEIGHT=152;double zoom=.7,panX=20,panY=90;Point last;int dragging=-1,pending=-1;boolean panning=false,moved=false;TerrainGraph moveBefore;Point2D.Double wireEnd;
        GraphCanvas(){setBackground(new Color(17,25,32));MouseAdapter mouse=new MouseAdapter(){public void mousePressed(MouseEvent e){if(app.busy)return;requestFocusInWindow();last=e.getPoint();if(SwingUtilities.isRightMouseButton(e)||SwingUtilities.isMiddleMouseButton(e)){panning=true;return;}if(!SwingUtilities.isLeftMouseButton(e))return;double x=worldX(e.getX()),y=worldY(e.getY());for(TerrainGraph.Node n:reverseNodes()){if(n.type!=TerrainGraph.Type.OUTPUT&&port(n,-1).distance(x,y)<12){pending=n.id;wireEnd=new Point2D.Double(x,y);repaint();return;}for(int slot=0;slot<n.input.length;slot++)if(port(n,slot).distance(x,y)<12){if(pending>=0){connect(pending,n.id,slot);pending=-1;wireEnd=null;}else if(n.input[slot]>=0){checkpoint();n.input[slot]=-1;changed(true);inspector();}repaint();return;}}
            selected=-1;for(TerrainGraph.Node n:reverseNodes())if(new Rectangle2D.Double(n.x,n.y,WIDTH,nodeHeight(n)).contains(x,y)){selected=n.id;if(y<n.y+32){dragging=n.id;moveBefore=graph.copy();moved=false;}break;}inspector();if(previewSelected.isSelected())queuePreview();repaint();}
            public void mouseDragged(MouseEvent e){if(app.busy)return;double dx=(e.getX()-last.x)/zoom,dy=(e.getY()-last.y)/zoom;if(panning){panX+=e.getX()-last.x;panY+=e.getY()-last.y;}else if(dragging>=0){TerrainGraph.Node n=graph.nodes.get(dragging);n.x=TerrainGenerator.clamp(n.x+dx,-99900,99900);n.y=TerrainGenerator.clamp(n.y+dy,-99900,99900);moved=true;}else if(pending>=0)wireEnd=new Point2D.Double(worldX(e.getX()),worldY(e.getY()));last=e.getPoint();repaint();}
            public void mouseMoved(MouseEvent e){if(pending>=0){wireEnd=new Point2D.Double(worldX(e.getX()),worldY(e.getY()));repaint();}}
            public void mouseReleased(MouseEvent e){if(app.busy){dragging=pending=-1;panning=false;return;}if(pending>=0&&!panning){double x=worldX(e.getX()),y=worldY(e.getY());for(TerrainGraph.Node n:graph.nodes.values())for(int slot=0;slot<n.input.length;slot++)if(port(n,slot).distance(x,y)<14){connect(pending,n.id,slot);pending=-1;wireEnd=null;repaint();break;}}if(dragging>=0&&moved){undo.push(moveBefore);redo.clear();while(undo.size()>30)undo.removeLast();changed(false);}dragging=-1;panning=false;}
            public void mouseWheelMoved(MouseWheelEvent e){double next=TerrainGenerator.clamp(zoom*Math.pow(1.12,-e.getPreciseWheelRotation()),.2,2);double ratio=next/zoom;panX=e.getX()-(e.getX()-panX)*ratio;panY=e.getY()-(e.getY()-panY)*ratio;zoom=next;repaint();}
        };addMouseListener(mouse);addMouseMotionListener(mouse);addMouseWheelListener(mouse);setFocusable(true);getInputMap().put(KeyStroke.getKeyStroke("ESCAPE"),"cancel-wire");getActionMap().put("cancel-wire",new AbstractAction(){private static final long serialVersionUID=1L;public void actionPerformed(ActionEvent e){pending=-1;wireEnd=null;repaint();}});}
        int nodeHeight(TerrainGraph.Node n){return Math.max(HEIGHT,64+n.input.length*29);}
        double worldX(double x){return (x-panX)/zoom;}double worldY(double y){return (y-panY)/zoom;}
        List<TerrainGraph.Node> reverseNodes(){ArrayList<TerrainGraph.Node> list=new ArrayList<>(graph.nodes.values());Collections.reverse(list);return list;}
        Point2D.Double port(TerrainGraph.Node n,int slot){return new Point2D.Double(n.x+(slot<0?WIDTH:0),n.y+(slot<0?53:49+slot*29));}
        void fit(){if(graph==null||graph.nodes.isEmpty())return;double minX=Double.POSITIVE_INFINITY,minY=minX,maxX=-minX,maxY=-minX;for(TerrainGraph.Node n:graph.nodes.values()){minX=Math.min(minX,n.x);minY=Math.min(minY,n.y);maxX=Math.max(maxX,n.x+WIDTH);maxY=Math.max(maxY,n.y+nodeHeight(n));}zoom=TerrainGenerator.clamp(Math.min(Math.max(200,getWidth()-70)/(maxX-minX),Math.max(200,getHeight()-90)/(maxY-minY)),.2,1.1);panX=(getWidth()-(maxX-minX)*zoom)/2-minX*zoom;panY=(getHeight()-(maxY-minY)*zoom)/2-minY*zoom;repaint();}
        Color color(TerrainGraph.Node n){return n.type==TerrainGraph.Type.OUTPUT?new Color(235,187,100):channelColor(n.type.channel());}
        void wire(Graphics2D g,Point2D a,Point2D b,Color color){g.setColor(color);g.setStroke(new BasicStroke(2.3f));double bend=b.getX()>=a.getX()?Math.max(45,(b.getX()-a.getX())*.45):38;g.draw(new CubicCurve2D.Double(a.getX(),a.getY(),a.getX()+bend,a.getY(),b.getX()-bend,b.getY(),b.getX(),b.getY()));}
        protected void paintComponent(Graphics graphics){super.paintComponent(graphics);Graphics2D g=(Graphics2D)graphics.create();try{g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(41,53,63));int grid=Math.max(12,(int)(32*zoom));for(int y=(int)panY%grid;y<getHeight();y+=grid)for(int x=(int)panX%grid;x<getWidth();x+=grid)g.fillRect(x,y,1,1);g.translate(panX,panY);g.scale(zoom,zoom);if(graph==null)return;for(TerrainGraph.Node to:graph.nodes.values())for(int slot=0;slot<to.input.length;slot++){TerrainGraph.Node from=graph.nodes.get(to.input[slot]);if(from!=null)wire(g,port(from,-1),port(to,slot),color(from));}if(pending>=0&&graph.nodes.containsKey(pending)&&wireEnd!=null)wire(g,port(graph.nodes.get(pending),-1),wireEnd,new Color(237,230,175));
            for(TerrainGraph.Node n:graph.nodes.values()){int x=(int)n.x,y=(int)n.y,cardHeight=nodeHeight(n);g.setColor(new Color(0,0,0,70));g.fillRoundRect(x+4,y+5,WIDTH,cardHeight,12,12);g.setColor(new Color(35,47,59));g.fillRoundRect(x,y,WIDTH,cardHeight,12,12);g.setColor(n.id==selected?color(n):new Color(67,86,99));g.setStroke(new BasicStroke(n.id==selected?2.5f:1));g.drawRoundRect(x,y,WIDTH,cardHeight,12,12);g.setColor(color(n));g.fillRoundRect(x,y,WIDTH,30,12,12);g.setColor(new Color(20,31,37));g.setFont(new Font("SansSerif",Font.BOLD,12));g.drawString(n.type.title,x+10,y+20);g.setFont(new Font("SansSerif",Font.PLAIN,10));g.setColor(new Color(181,202,213));g.drawString("#"+n.id,x+WIDTH-27,y+45);
                float[] field=fields.get(n.id);if(field!=null){BufferedImage thumb=thumbnails.computeIfAbsent(n.id,k->nodeImage(n,field,environments.get(n.id),app.sea.getValue()));g.drawImage(thumb,x+76,y+57,95,83,null);}else{g.setColor(new Color(23,33,42));g.fillRoundRect(x+76,y+57,95,83,5,5);g.setColor(new Color(106,127,141));g.drawString(n.type.mask?"MASK":"HEIGHTFIELD",x+86,y+102);}
                for(int slot=0;slot<n.input.length;slot++){Point2D.Double p=port(n,slot);g.setColor(channelColor(n.type.inputChannel(slot)));g.fillOval((int)p.x-6,(int)p.y-6,12,12);g.setColor(new Color(213,225,232));String label=n.type==TerrainGraph.Type.OUTPUT?n.type.port(slot):(n.type==TerrainGraph.Type.TREES||n.type==TerrainGraph.Type.ROCKS)&&slot==1?"Mask":n.type.inputChannel(slot)==TerrainGraph.Channel.CLIMATE?"Climate":n.type==TerrainGraph.Type.BLEND?(slot==0?"A":slot==1?"B":"Mask"):"In";g.drawString(label,x+12,(int)p.y+4);}if(n.type!=TerrainGraph.Type.OUTPUT){Point2D.Double p=port(n,-1);g.setColor(color(n));g.fillOval((int)p.x-6,(int)p.y-6,12,12);}
            }
        }finally{g.dispose();}}
    }
